from discount import apply_discount
from price import subtotal

class ShopTest(unittest.TestCase):
	def test_discount(self):
		self.assertEqual(apply_discount(20000, 10), 18000)

	def test_subtotal_multiple_items(self):
		self.assertEqual(subtotal([(1000, 2), (500, 3)]), 3500)

	def test_subtotal_empty(self):
		self.assertEqual(subtotal([]), 0)

	def test_subtotal_zero_quantity(self):
		self.assertEqual(subtotal([(1000, 0), (250, 4)]), 1000)
